import fs from 'node:fs';
import assert from 'node:assert/strict';
import {PythonSession} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/index.ts';
const mode=process.argv[2],source=fs.readFileSync(process.argv[3],'utf8'),controller=new AbortController();
let reads=0,writes=0;
const session=new PythonSession({limits:{maxSteps:2000000,maxAllocatedBytes:24000000,maxDepth:100},hashSeed:[1n,2n],signal:controller.signal,
input:{readLine(){reads++;const bytes=Buffer.alloc(1);let line='';while(fs.readSync(0,bytes,0,1,null)){line+=bytes.toString();if(line.endsWith('\n'))break;}if(mode==='return'||mode==='throw')controller.abort();if(mode==='throw')throw Error('service failed after read');return line||null;}},
output:{write(text){writes++;fs.writeSync(1,text);},flush(){/* writeSync has no userspace output buffer to flush. */}}});
const result=session.exec(source);
if(mode==='return'||mode==='throw'){
assert.deepEqual(result,{status:'terminated',reason:'cancelled',message:'execution cancelled'});assert.deepEqual(session.eval('1'),{status:'terminated',reason:'cancelled',message:'execution cancelled'});assert.equal(reads,1);assert.equal(writes,0);
}else assert.equal(result.status,'ok');

fs.writeSync(2,JSON.stringify({reads,writes})+"\n");

